// The Q15 table is generated by tools/gen/lut.ts and committed; this test regenerates it in memory and compares.
import fs from 'node:fs';
import { describe, expect, it } from 'vitest';
import { LUT_PATH, QUARTER_STEPS, buildLutSource, buildQuarterTable } from '../../tools/gen/lut';
import { SIN_QUARTER_Q15, SIN_QUARTER_STEPS } from '../../src/sim/sinLut';

describe('sin table generated by tools/gen/lut.ts', () => {
  it('the committed src/sim/sinLut.ts equals the regenerated text byte for byte', () => {
    expect(fs.readFileSync(LUT_PATH, 'utf8')).toBe(buildLutSource());
  });

  it('has 1025 entries, starts at 0, ends at exactly 1.0 (32768), is non-decreasing and symmetric around the peak', () => {
    expect(SIN_QUARTER_STEPS).toBe(QUARTER_STEPS);
    expect(SIN_QUARTER_Q15.length).toBe(1025);
    expect(SIN_QUARTER_Q15[0]).toBe(0);
    expect(SIN_QUARTER_Q15[1024]).toBe(32768);
    for (let i = 1; i <= 1024; i++) expect(SIN_QUARTER_Q15[i] as number).toBeGreaterThanOrEqual(SIN_QUARTER_Q15[i - 1] as number);
    // sin(x) = cos(pi/2 - x): the table is its own mirror up to the rounding of the two sides.
    expect(Array.from(SIN_QUARTER_Q15)).toEqual(buildQuarterTable());
  });

  it('every entry is the rounded sine (and not off by one)', () => {
    for (let i = 0; i <= 1024; i++) {
      const exact = Math.sin((i / 4096) * 2 * Math.PI) * 32768;
      expect(Math.abs((SIN_QUARTER_Q15[i] as number) - exact)).toBeLessThanOrEqual(0.5);
    }
  });
});
